CREATE TABLE users (id uuid PRIMARY KEY, email varchar(254) NOT NULL UNIQUE CHECK(email=lower(email)), name varchar(120) NOT NULL, password_hash text, verified boolean NOT NULL DEFAULT false, status varchar(12) NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','DISABLED')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE roles (name varchar(20) PRIMARY KEY CHECK(name IN ('USER','EDITOR','ADMIN','SUPER_ADMIN')));
CREATE TABLE user_roles(user_id uuid REFERENCES users(id), role_name varchar(20) REFERENCES roles(name), PRIMARY KEY(user_id,role_name));
CREATE TABLE auth_identities(id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), provider varchar(20) NOT NULL, subject varchar(255) NOT NULL, UNIQUE(provider,subject));
CREATE TABLE refresh_sessions(id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), family_id uuid NOT NULL, token_hash varchar(64) NOT NULL UNIQUE, expires_at timestamptz NOT NULL, revoked_at timestamptz, mfa_verified boolean NOT NULL DEFAULT false, authenticated_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX refresh_user_idx ON refresh_sessions(user_id); CREATE INDEX refresh_family_idx ON refresh_sessions(family_id);
CREATE TABLE email_otp_challenges(id uuid PRIMARY KEY, user_id uuid REFERENCES users(id), email varchar(254) NOT NULL, purpose varchar(30) NOT NULL CHECK(purpose IN ('EMAIL_VERIFICATION','PASSWORD_RESET')), code_hash varchar(64) NOT NULL, attempts integer NOT NULL DEFAULT 0 CHECK(attempts BETWEEN 0 AND 5), expires_at timestamptz NOT NULL, consumed_at timestamptz, reset_token_hash varchar(64), reset_token_expires_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX otp_account_idx ON email_otp_challenges(email,purpose,created_at);
CREATE TABLE mfa_totp(user_id uuid PRIMARY KEY REFERENCES users(id), encrypted_secret text NOT NULL, enabled boolean NOT NULL DEFAULT false, last_counter bigint NOT NULL DEFAULT -1, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE mfa_recovery_codes(id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), code_hash varchar(64) NOT NULL, used_at timestamptz, UNIQUE(user_id,code_hash));
CREATE TABLE media_files(id uuid PRIMARY KEY, original_filename varchar(255) NOT NULL, stored_filename varchar(255) NOT NULL, mime_type varchar(80) NOT NULL, file_size bigint NOT NULL CHECK(file_size>0), content_hash varchar(64) NOT NULL, data bytea NOT NULL, alt_text varchar(500) NOT NULL DEFAULT '', is_public boolean NOT NULL DEFAULT false, uploaded_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE content_items(id uuid PRIMARY KEY, kind varchar(20) NOT NULL CHECK(kind IN ('POST','PAGE','BRANCH','PRODUCT','PARTNER','CERTIFICATION','CATEGORY','HERO')), status varchar(12) NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','PUBLISHED','ARCHIVED')), featured boolean NOT NULL DEFAULT false, featured_media_id uuid REFERENCES media_files(id), author_id uuid NOT NULL REFERENCES users(id), metadata jsonb NOT NULL DEFAULT '{}', published_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), updated_by uuid REFERENCES users(id));
CREATE INDEX content_listing_idx ON content_items(kind,status,published_at DESC);
CREATE TABLE content_translations(id uuid PRIMARY KEY, content_id uuid NOT NULL REFERENCES content_items(id), locale varchar(2) NOT NULL CHECK(locale IN ('vi','en')), title varchar(200) NOT NULL, slug varchar(180) NOT NULL, excerpt varchar(1000) NOT NULL DEFAULT '', content jsonb NOT NULL DEFAULT '{"type":"doc","content":[]}', seo_title varchar(200) NOT NULL DEFAULT '', seo_description varchar(320) NOT NULL DEFAULT '', UNIQUE(content_id,locale), UNIQUE(locale,slug));
CREATE INDEX translation_title_idx ON content_translations(locale,title);
CREATE TABLE post_categories(post_id uuid REFERENCES content_items(id), category_id uuid REFERENCES content_items(id), PRIMARY KEY(post_id,category_id));
CREATE TABLE homepage_sections(id uuid PRIMARY KEY, section_key varchar(30) NOT NULL UNIQUE, enabled boolean NOT NULL DEFAULT true, position integer NOT NULL CHECK(position>=0), headline_vi varchar(200) NOT NULL DEFAULT '', headline_en varchar(200) NOT NULL DEFAULT '', subheadline_vi varchar(500) NOT NULL DEFAULT '', subheadline_en varchar(500) NOT NULL DEFAULT '', content_ids uuid[] NOT NULL DEFAULT '{}');
CREATE TABLE contact_messages(id uuid PRIMARY KEY, full_name varchar(120) NOT NULL, company varchar(200) NOT NULL DEFAULT '', email varchar(254) NOT NULL, phone varchar(40) NOT NULL DEFAULT '', subject varchar(200) NOT NULL, message text NOT NULL, status varchar(12) NOT NULL DEFAULT 'NEW' CHECK(status IN ('NEW','READ','REPLIED','ARCHIVED')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE site_settings(key varchar(80) PRIMARY KEY, value varchar(2000) NOT NULL);
CREATE TABLE audit_logs(id uuid PRIMARY KEY, actor_user_id uuid REFERENCES users(id), action varchar(80) NOT NULL, entity_type varchar(40) NOT NULL, entity_id varchar(100), timestamp timestamptz NOT NULL DEFAULT now(), ip_address varchar(64), user_agent varchar(250), metadata jsonb NOT NULL DEFAULT '{}');
CREATE INDEX audit_time_idx ON audit_logs(timestamp DESC);
CREATE TABLE rate_limit_buckets(bucket_key varchar(180) PRIMARY KEY, window_start timestamptz NOT NULL, requests integer NOT NULL CHECK(requests>=0));
